public static void main(String[] args) {
    PrintWriter out = new PrintWriter(System.out);
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int M = sc.nextInt();
    int[] X = new int[M+1];
    for (int i = 1; i <= M; i++) {
        X[i] = sc.nextInt();
    }

    long[] cost = new long[N+1];
    // Prepare cumulative sum
    for (int i = 1; i < M; i++) {
        int left;
        int right;
        if (X[i] >= X[i+1]){
            left = X[i] - X[i+1];
            right = N - X[i] + X[i+1];
        } else {
            left = X[i] + N - X[i+1];
            right = X[i+1] - X[i];
        }
        cost[X[i]] += right - left;
        cost[X[i+1]] -= right - left;
    }
    // Imos method
    for (int i = 1; i < N; i++) {
        cost[i+1] += cost[i];
    }
    cost[1] += cost[N];

    long totalCost = 0;
    for (int i = 1; i < M; i++) {
        if (X[i] >= X[i+1]) {
            totalCost += X[i] - X[i+1];
        } else {
            totalCost += X[i+1] - X[i];
        }
    }

    long answer = totalCost;
    for (int i = 1; i <= N; i++) {
        answer = Math.min(answer, totalCost - cost[i]);
    }

    System.out.println(answer);
}
